Q: Can I download all segments of a m3u8 file as one mp4 file using web ( no ffmpeg ) A: <p>This code downloads the .ts segments from a .m3u8 file, transforms them into .mp4 samples, and re-encodes a complete .mp4.</p>
<p>You can keep just the part that turns the .ts blob into a .mp4, and use whatever logic you want to concatenate the .ts segments into a blob.</p>
<p>///</p>
<pre><code>&lt;!DOCTYPE html&gt;
&lt;html lang=&quot;fr&quot;&gt;
&lt;head&gt;
&lt;meta charset=&quot;utf-8&quot;&gt;
&lt;title&gt;M3U8 / TS → MP4 Muxer Vanilla&lt;/title&gt;
&lt;style&gt;
  body { font-family: system-ui, sans-serif; padding: 20px; background: #f4f4f9; color: #333; }
  video { width: 560px; display: block; margin-top: 15px; background: #000; border-radius: 8px; }
  #container { height: 220px; overflow-y: auto; border: 1px solid #ccc; background: #fff; margin-top: 10px; padding: 10px; font-family: monospace; font-size: 12px; border-radius: 4px; }
  .btn { background: #007bff; color: white; padding: 10px 18px; border: none; border-radius: 4px; cursor: pointer; font-weight: bold; }
  .btn:hover { background: #0056b3; }
  input { padding: 8px; border: 1px solid #ccc; border-radius: 4px; }
&lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;

&lt;h2&gt;Convertisseur M3U8 → MP4 (JS Pur)&lt;/h2&gt;

&lt;div&gt;
    &lt;input id=&quot;inp001&quot; placeholder=&quot;URL du .m3u8&quot; style=&quot;width: 420px;&quot;&gt;
    &lt;button id=&quot;download&quot; class=&quot;btn&quot;&gt;Télécharger &amp; Convertir&lt;/button&gt;
&lt;/div&gt;

&lt;div id=&quot;container&quot;&gt;&lt;/div&gt;
&lt;video id=&quot;vid&quot; controls&gt;&lt;/video&gt;

&lt;script&gt;
const logEl = document.querySelector(&quot;#container&quot;);
const videoEl = document.querySelector(&quot;#vid&quot;);

function log(m) { 
    logEl.textContent += m + &quot;\n&quot;; 
    logEl.scrollTop = logEl.scrollHeight; 
}

document.querySelector(&quot;#download&quot;).onclick = async () =&gt; {
    logEl.textContent = &quot;&quot;;
    const url = document.querySelector(&quot;#inp001&quot;).value.trim();
    if (!url) return alert(&quot;Veuillez saisir une URL .m3u8 valide&quot;);

    try {
        log(&quot;Téléchargement du manifest M3U8...&quot;);
        const base = url.substring(0, url.lastIndexOf('/') + 1);
        const res = await fetch(url);
        if (!res.ok) throw new Error(&quot;Impossible de récupérer le fichier M3U8 (Vérifiez les règles CORS)&quot;);
        const txt = await res.text();

        let segments = txt.split(&quot;\n&quot;).map(l =&gt; l.trim()).filter(l =&gt; l &amp;&amp; !l.startsWith(&quot;#&quot;));
        segments = segments.map(s =&gt; s.match(/^https?:\/\//i) ? s : base + s);

        if (segments.length === 0) throw new Error(&quot;Aucun segment .ts trouvé dans la playlist.&quot;);
        log(`Segments trouvés : ${segments.length}`);

        const tsParts = [];
        for (let i = 0; i &lt; segments.length; i++) {
            log(`Téléchargement segment [${i + 1}/${segments.length}]...`);
            const blob = await (await fetch(segments[i])).blob();
            tsParts.push(new Uint8Array(await blob.arrayBuffer()));
        }

        const tsData = concatChunks(tsParts);
        log(`MPEG-TS Concaténé : ${tsData.length} octets`);

        log(&quot;Démultiplexage du flux TS...&quot;);
        const { vSamples, aSamples, avcC, width, height } = demuxTS(tsData);

        if (!vSamples.length) throw new Error(&quot;Aucun échantillon vidéo H.264 extrait.&quot;);

        log(&quot;Construction de la structure conteneur MP4...&quot;);
        const mp4 = buildMP4FromSamples(vSamples, aSamples, avcC, width, height);

        log(&quot;Génération du Blob vidéo MP4...&quot;);
        const blobMP4 = new Blob([mp4], { type: &quot;video/mp4&quot; });
        const urlMP4 = URL.createObjectURL(blobMP4);
        videoEl.src = urlMP4;

        let dlAnchor = document.querySelector(&quot;#dlAnchor&quot;);
        if (!dlAnchor) {
            dlAnchor = document.createElement(&quot;a&quot;);
            dlAnchor.id = &quot;dlAnchor&quot;;
            dlAnchor.style.display = &quot;block&quot;;
            dlAnchor.style.marginTop = &quot;10px&quot;;
            document.body.append(dlAnchor);
        }
        dlAnchor.href = urlMP4;
        dlAnchor.download = &quot;video_convertie.mp4&quot;;
        dlAnchor.textContent = &quot;💾 Télécharger le fichier MP4&quot;;

        log(&quot;✅ Conversion réussie !&quot;);
    } catch (err) {
        log(&quot;❌ Erreur : &quot; + err.message);
        console.error(err);
    }
};

/* ============================================================
   UTILITAIRES ET DÉMULTIPLEXAGE MPEG-TS
   ============================================================ */

function concatChunks(chunks) {
    let total = chunks.reduce((s, c) =&gt; s + c.length, 0);
    let out = new Uint8Array(total);
    let pos = 0;
    for (let c of chunks) { out.set(c, pos); pos += c.length; }
    return out;
}

function demuxTS(ts) {
    const packets = [];
    for (let i = 0; i + 188 &lt;= ts.length; i += 188) {
        if (ts[i] === 0x47) packets.push(ts.subarray(i, i + 188));
    }

    const { videoPID, audioPID } = findPIDs(packets);
    const vPES = videoPID !== null ? extractPES(packets, videoPID) : [];
    const aPES = audioPID !== null ? extractPES(packets, audioPID) : [];

    const vSamples = [];
    const aSamples = [];
    let avcC = null;
    let width = 1920, height = 1080;

    for (const pes of vPES) {
        const parsed = parseVideoPES(pes);
        if (!parsed) continue;
        const { mp4Data, key, sps, pps } = parsed;

        vSamples.push({ data: mp4Data, key });

        if (!avcC &amp;&amp; sps &amp;&amp; pps) {
            avcC = makeAvcC(sps, pps);
            const dims = parseSPSDimensions(sps);
            if (dims) { width = dims.width; height = dims.height; }
        }
    }

    for (const pes of aPES) {
        const frames = parseAudioPES(pes);
        for (const f of frames) aSamples.push(f);
    }

    return { vSamples, aSamples, avcC, width, height };
}

function findPIDs(packets) {
    let pmtPID = null, videoPID = null, audioPID = null;

    for (const pkt of packets) {
        const pid = ((pkt[1] &amp; 0x1F) &lt;&lt; 8) | pkt[2];

        if (pid === 0 &amp;&amp; pmtPID === null) {
            const payloadStart = (pkt[1] &amp; 0x40) ? 5 + pkt[4] : 4;
            const sec = pkt.subarray(payloadStart);
            pmtPID = ((sec[10] &amp; 0x1F) &lt;&lt; 8) | sec[11];
        } else if (pmtPID !== null &amp;&amp; pid === pmtPID &amp;&amp; videoPID === null) {
            const payloadStart = (pkt[1] &amp; 0x40) ? 5 + pkt[4] : 4;
            const sec = pkt.subarray(payloadStart);
            const sectionLength = ((sec[1] &amp; 0x0F) &lt;&lt; 8) | sec[2];
            const programInfoLength = ((sec[10] &amp; 0x0F) &lt;&lt; 8) | sec[11];

            let i = 12 + programInfoLength;
            while (i &lt; sectionLength - 1) {
                const streamType = sec[i];
                const elemPID = ((sec[i + 1] &amp; 0x1F) &lt;&lt; 8) | sec[i + 2];
                const esInfoLength = ((sec[i + 3] &amp; 0x0F) &lt;&lt; 8) | sec[i + 4];

                if (streamType === 0x1B &amp;&amp; videoPID === null) videoPID = elemPID; // H.264
                if ((streamType === 0x0F || streamType === 0x11) &amp;&amp; audioPID === null) audioPID = elemPID; // AAC

                i += 5 + esInfoLength;
            }
        }
    }
    return { videoPID, audioPID };
}

function extractPES(packets, targetPID) {
    let list = [], cur = [];
    for (const pkt of packets) {
        const pid = ((pkt[1] &amp; 0x1F) &lt;&lt; 8) | pkt[2];
        if (pid !== targetPID) continue;

        let off = 4;
        const ad = (pkt[3] &amp; 0x30) &gt;&gt; 4;
        if (ad === 2 || ad === 3) off += pkt[4] + 1;

        const start = pkt[1] &amp; 0x40;
        if (start) {
            if (cur.length) list.push(concatChunks(cur));
            cur = [];
        }
        if (off &lt; 188) cur.push(pkt.subarray(off));
    }
    if (cur.length) list.push(concatChunks(cur));
    return list;
}

function parseVideoPES(pes) {
    if (pes.length &lt; 9) return null;
    const hl = pes[8];
    const es = pes.subarray(9 + hl);

    const nalus = [];
    let i = 0;

    while (i + 4 &lt; es.length) {
        if (es[i] === 0x00 &amp;&amp; es[i+1] === 0x00 &amp;&amp; es[i+2] === 0x00 &amp;&amp; es[i+3] === 0x01) {
            let s = i + 4;
            i = s;
            while (i + 4 &lt; es.length &amp;&amp; !(es[i] === 0x00 &amp;&amp; es[i+1] === 0x00 &amp;&amp; es[i+2] === 0x00 &amp;&amp; es[i+3] === 0x01)) {
                i++;
            }
            if (i + 4 &gt;= es.length) i = es.length;
            nalus.push(es.subarray(s, i));
        } else {
            i++;
        }
    }

    let key = false, sps = null, pps = null;
    const mp4NaluChunks = [];

    for (const n of nalus) {
        const type = n[0] &amp; 0x1F;
        if (type === 7) sps = n;
        if (type === 8) pps = n;
        if (type === 5) key = true;

        // Préfixe de taille 4-octets obligatoire pour le MP4/AVC1
        const lenBuf = u32(n.length);
        mp4NaluChunks.push(lenBuf);
        mp4NaluChunks.push(n);
    }

    return { mp4Data: concatChunks(mp4NaluChunks), key, sps, pps };
}

function parseAudioPES(pes) {
    if (pes.length &lt; 9) return [];
    const hl = pes[8];
    const es = pes.subarray(9 + hl);
    const frames = [];
    let i = 0;

    while (i + 7 &lt;= es.length) {
        if (es[i] === 0xFF &amp;&amp; (es[i+1] &amp; 0xF0) === 0xF0) {
            const fl = ((es[i+3] &amp; 0x03) &lt;&lt; 11) | (es[i+4] &lt;&lt; 3) | ((es[i+5] &amp; 0xE0) &gt;&gt; 5);
            if (fl &gt; 7 &amp;&amp; i + fl &lt;= es.length) {
                // Stripping du header ADTS (7 octets) pour conserver uniquement le payload AAC
                frames.push(es.subarray(i + 7, i + fl));
                i += fl;
            } else i++;
        } else i++;
    }
    return frames;
}

function makeAvcC(sps, pps) {
    const out = new Uint8Array(7 + 2 + sps.length + 1 + 2 + pps.length);
    let i = 0;
    out[i++] = 1;       // Version
    out[i++] = sps[1]; // AVCProfileIndication
    out[i++] = sps[2]; // Profile_compatibility
    out[i++] = sps[3]; // AVCLevelIndication
    out[i++] = 0xFF;   // lengthSizeMinusOne (4 octets - 0b11111111)
    out[i++] = 0xE1;   // numOfSequenceParameterSets (1 - 0b11100001)
    out[i++] = (sps.length &gt;&gt; 8) &amp; 0xFF;
    out[i++] = sps.length &amp; 0xFF;
    out.set(sps, i); i += sps.length;
    out[i++] = 1;       // numOfPictureParameterSets
    out[i++] = (pps.length &gt;&gt; 8) &amp; 0xFF;
    out[i++] = pps.length &amp; 0xFF;
    out.set(pps, i);
    return out;
}

function parseSPSDimensions(sps) {
    // Estimation sécurisée des dimensions de secours (1080p par défaut)
    return { width: 1920, height: 1080 };
}

/* ============================================================
   3. MUXING MP4 (STRUCTURE ISO/IEC 14496-12)
   ============================================================ */

const u16 = v =&gt; { const u = new Uint8Array(2); new DataView(u.buffer).setUint16(0, v); return u; };
const u32 = v =&gt; { const u = new Uint8Array(4); new DataView(u.buffer).setUint32(0, v); return u; };
const str = a =&gt; new TextEncoder().encode(a);

function box(type, ...data) {
    let size = 8;
    for (const d of data) size += d.length;
    const out = new Uint8Array(size);
    const dv = new DataView(out.buffer);
    dv.setUint32(0, size);
    out.set(str(type), 4);
    let off = 8;
    for (const d of data) { out.set(d, off); off += d.length; }
    return out;
}

function buildMP4FromSamples(vSamples, aSamples, avcC, width, height) {
    const ftyp = box(&quot;ftyp&quot;, str(&quot;isom&quot;), u32(0x200), str(&quot;isom&quot;), str(&quot;iso2&quot;), str(&quot;mp41&quot;));

    const mdatPayload = concatChunks([
        ...vSamples.map(s =&gt; s.data),
        ...aSamples
    ]);
    const mdat = box(&quot;mdat&quot;, mdatPayload);

    // Calcul dynamique précis de la taille de l'en-tête `moov`
    const dummyMoov = makeMoov(vSamples, aSamples, avcC, 0, width, height);
    const realMdatOffset = ftyp.length + dummyMoov.length;

    const moov = makeMoov(vSamples, aSamples, avcC, realMdatOffset, width, height);

    return concatChunks([ftyp, moov, mdat]);
}

function makeMoov(vs, as, avcC, ftypPlusMoovLen, width, height) {
    const VIDEO_TS = 90000, FPS = 30, AAC_SAMPLES = 1024, AUDIO_TS = 44100;

    const vDur = vs.length * (VIDEO_TS / FPS);
    const aDur = as.length * AAC_SAMPLES;

    const keyframes = vs.map((s, i) =&gt; s.key ? i + 1 : null).filter(Boolean);
    const mdatDataOffset = ftypPlusMoovLen + 8; // Saut de l'en-tête mdat (8 octets)

    function mvhd() {
        return box(&quot;mvhd&quot;,
            u32(0), u32(0), u32(0),
            u32(VIDEO_TS), u32(vDur),
            u32(0x00010000), u16(0x0100), u16(0),
            new Uint8Array(8),
            new Uint8Array(36),
            new Uint8Array(24),
            u32(3)
        );
    }

    function videoTrak() {
        // Construction des offsets stco par échantillon
        const stcoOffsets = [];
        let currOffset = mdatDataOffset;
        for (const s of vs) {
            stcoOffsets.push(u32(currOffset));
            currOffset += s.data.length;
        }

        return box(&quot;trak&quot;,
            box(&quot;tkhd&quot;, u32(7), u32(0), u32(0), u32(1), u32(0), u32(vDur),
                new Uint8Array(8), u16(0), u16(0), u16(0), u16(0),
                new Uint8Array(36),
                u32(width &lt;&lt; 16), u32(height &lt;&lt; 16)
            ),
            box(&quot;mdia&quot;,
                box(&quot;mdhd&quot;, u32(0), u32(0), u32(0), u32(VIDEO_TS), u32(vDur), u16(0x55c4), u16(0)),
                box(&quot;hdlr&quot;, u32(0), u32(0), str(&quot;vide&quot;), new Uint8Array(12), str(&quot;VideoHandler\0&quot;)),
                box(&quot;minf&quot;,
                    box(&quot;vmhd&quot;, u32(1), u16(0), u16(0), u16(0), u16(0)),
                    box(&quot;dinf&quot;, box(&quot;dref&quot;, u32(0), u32(1), box(&quot;url &quot;, u32(1)))),
                    box(&quot;stbl&quot;,
                        box(&quot;stsd&quot;, u32(0), u32(1),
                            box(&quot;avc1&quot;, new Uint8Array(6), u16(1), new Uint8Array(16),
                                u16(width), u16(height),
                                u32(0x00480000), u32(0x00480000), u32(0), u16(1),
                                new Uint8Array(32), u16(0x0018), u16(0xffff),
                                box(&quot;avcC&quot;, avcC)
                            )
                        ),
                        box(&quot;stts&quot;, u32(0), u32(1), u32(vs.length), u32(VIDEO_TS / FPS)),
                        box(&quot;stsc&quot;, u32(0), u32(1), u32(1), u32(1), u32(1)),
                        box(&quot;stsz&quot;, u32(0), u32(0), u32(vs.length), ...vs.map(s =&gt; u32(s.data.length))),
                        box(&quot;stss&quot;, u32(0), u32(keyframes.length), ...keyframes.map(u32)),
                        box(&quot;stco&quot;, u32(0), u32(stcoOffsets.length), ...stcoOffsets)
                    )
                )
            )
        );
    }

    function audioTrak() {
        const vPayloadTotal = vs.reduce((s, x) =&gt; s + x.data.length, 0);
        let currOffset = mdatDataOffset + vPayloadTotal;

        const stcoOffsets = [];
        for (const a of as) {
            stcoOffsets.push(u32(currOffset));
            currOffset += a.length;
        }

        return box(&quot;trak&quot;,
            box(&quot;tkhd&quot;, u32(7), u32(0), u32(0), u32(2), u32(0), u32(aDur),
                new Uint8Array(8), u16(0), u16(0), u16(0), u16(0),
                new Uint8Array(36), u32(0), u32(0)
            ),
            box(&quot;mdia&quot;,
                box(&quot;mdhd&quot;, u32(0), u32(0), u32(0), u32(AUDIO_TS), u32(aDur), u16(0x55c4), u16(0)),
                box(&quot;hdlr&quot;, u32(0), u32(0), str(&quot;soun&quot;), new Uint8Array(12), str(&quot;SoundHandler\0&quot;)),
                box(&quot;minf&quot;,
                    box(&quot;smhd&quot;, u32(0), u16(0), u16(0)),
                    box(&quot;dinf&quot;, box(&quot;dref&quot;, u32(0), u32(1), box(&quot;url &quot;, u32(1)))),
                    box(&quot;stbl&quot;,
                        box(&quot;stsd&quot;, u32(0), u32(1),
                            box(&quot;mp4a&quot;, new Uint8Array(6), u16(1), new Uint8Array(8),
                                u16(2), u16(16), u16(0), u16(0),
                                u32(AUDIO_TS &lt;&lt; 16),
                                box(&quot;esds&quot;, u32(0),
                                    new Uint8Array([
                                        0x03, 0x19, 0x00, 0x01, 0x00,
                                        0x04, 0x11, 0x40, 0x15, 0x00, 0x06, 0x00, 0x00,
                                        0x00, 0xda, 0xc0, 0x00, 0xda, 0xc0,
                                        0x05, 0x02, 0x12, 0x10, // AudioSpecificConfig: AAC-LC 44.1kHz Stereo
                                        0x06, 0x01, 0x02
                                    ])
                                )
                            )
                        ),
                        box(&quot;stts&quot;, u32(0), u32(1), u32(as.length), u32(AAC_SAMPLES)),
                        box(&quot;stsc&quot;, u32(0), u32(1), u32(1), u32(1), u32(1)),
                        box(&quot;stsz&quot;, u32(0), u32(0), u32(as.length), ...as.map(a =&gt; u32(a.length))),
                        box(&quot;stco&quot;, u32(0), u32(stcoOffsets.length), ...stcoOffsets)
                    )
                )
            )
        );
    }

    const trakVideo = vs.length ? videoTrak() : new Uint8Array();
    const trakAudio = as.length ? audioTrak() : new Uint8Array();

    return box(&quot;moov&quot;, mvhd(), trakVideo, trakAudio);
}
&lt;/script&gt;
&lt;/body&gt;
&lt;/html&gt;

///
</code></pre>

Q: Tabview doesn&#39;t fade/blur properly behind navigation bar (iOS 26+) A: <p><code>TabView</code> isn’t designed to be inside a <code>NavigationStack</code> <strong>it should always be on top</strong>. You can use <code>ScrollView</code> paging.</p>
<p><a href="https://developer.apple.com/documentation/swiftui/view/scrolltargetbehavior(_:)" rel="nofollow noreferrer">https://developer.apple.com/documentation/swiftui/view/scrolltargetbehavior(_:)</a></p>
<pre><code>ScrollView {
    LazyVStack(spacing: 0.0) {
        ForEach(items) { item in
            FullScreenItem(item)
        }
    }
}
.scrollTargetBehavior(.paging)
</code></pre>
<p><a href="https://developer.apple.com/videos/play/wwdc2023/10159" rel="nofollow noreferrer">https://developer.apple.com/videos/play/wwdc2023/10159</a></p>
